cards.solution:
public class Crowd : MonoBehaviour
{
    NativeArray<float3> pos, vel;       // 100 000 particles
    NativeArray<Agent> agents;          // 200 agents
    JobHandle moveHandle, pathHandle;

    void Update()
    {
        var move = new MoveJob { pos = pos, vel = vel, dt = Time.deltaTime };   // IJobFor
        var path = new PathJob { agents = agents };                             // IJobFor
        // cheap iterations: big batches; expensive, uneven ones: batch of 1
        moveHandle = move.ScheduleParallel(pos.Length, 64, default);
        pathHandle = path.ScheduleParallel(agents.Length, 1, default);
        JobHandle.ScheduleBatchedJobs();
    }
}
